}

async fn send_snapshot(socket: &mut WebSocket, state: &AppState) -> Result<(), axum::Error> {
    let initial = [
        // First, so a reconnecting tab stamps clips against the live epoch
        // instead of whatever it held before it dropped.
        Event::Json(
