fn thinking_alias(value: &str) -> Option<&'static str> {
    match value {
        "none" | "no thinking" | "without thinking" => Some("off"),
        "lowest" | "min" => Some("minimal"),
        "mid" | "normal" => Some("medium"),
        "extra high" | "x high" | "very high" => Some("xhigh"),
        "maximum" | "highest" => Some("max"),
        "default" => Some(""),
        _ => None,
    }
