#[cfg(test)]
mod tests {
    use super::*;
    use crate::pbx::OPERATOR;
    use crate::registry::Registry;
    use axum::body::Body;
    use axum::http::{Method, Request, StatusCode};
    use http_body_util::BodyExt;
    use std::collections::HashMap;
    use std::future::pending;
    use tokio::sync::oneshot;
    use tokio::time::{timeout, Duration};
    use tower::ServiceExt;

    fn state() -> AppState {
        state_with_stt(None)
    }

    fn state_with_stt(stt: Option<String>) -> AppState {
        let board = Switchboard::new(
            Registry::new(vec![]),
            "pi".into(),
            None,
            "".into(),
            None,
            None,
            None,
            "medium".into(),
            ".cache".into(),
            true,
            "".into(),
            "".into(),
            "".into(),
            "".into(),
            HashMap::new(),
        );
        AppState::new(
            board,
            TranscriptLog::new(10),
            Speaker::from_values(
                100,
                &HashMap::from([("ELEVENLABS_API_KEY".into(), "test-key".into())]),
            ),
            SttAdapter::from_command(stt),
        )
    }

    async fn request_json(
        state: &AppState,
        method: Method,
        path: &str,
        body: Option<Value>,
    ) -> (StatusCode, Value) {
        let mut request = Request::builder().method(method).uri(path);
        let body = match body {
            Some(value) => {
                request = request.header("content-type", "application/json");
                Body::from(value.to_string())
            }
            None => Body::empty(),
        };
        let response = state
            .clone()
            .router(None)
            .oneshot(request.body(body).unwrap())
            .await
            .unwrap();
        let status = response.status();
        let bytes = response.into_body().collect().await.unwrap().to_bytes();
        let value = serde_json::from_slice(&bytes).unwrap();
        (status, value)
    }

    #[tokio::test]
    async fn http_contract_exposes_status_health_and_page_controls() {
        let state = state();
        let (code, status) = request_json(&state, Method::GET, "/status", None).await;
        assert_eq!(code, StatusCode::OK);
        assert_eq!(status["type"], "status");
        assert_eq!(status["route"], OPERATOR);
